<?php
declare(strict_types=1);
require_once __DIR__ . '/config/role_portal_auth.php';
$error=null;$success=null;$users=[];$csrf='';$pendingRecovery=0;
try{
    $pdo=business_db();role_portal_ensure($pdo);$actor=security_step17_current_user($pdo);
    if(!security_step17_has_permission($pdo,'security.users.manage',$actor)){header('Location: access_denied.php?permission=security.users.manage');exit;}
    $ctx=security_step17_context($pdo);$orgId=(int)$ctx['organization_id'];$csrf=security_step17_csrf();
    if($_SERVER['REQUEST_METHOD']==='POST'){
        security_step17_verify_csrf((string)($_POST['csrf']??''));$action=(string)($_POST['action']??'');
        if($action==='create'){
            $p=(string)($_POST['temporary_password']??'');if(!hash_equals($p,(string)($_POST['confirm_password']??'')))throw new RuntimeException('Temporary password confirmation does not match.');
            $id=role_portal_create_user($pdo,(string)($_POST['full_name']??''),(string)($_POST['email']??''),(string)($_POST['mobile']??''),(string)($_POST['role_code']??'customer'),$p);
            $success='Role account #'.$id.' created. The user must change the temporary password at first sign-in.';
        }elseif($action==='update'){
            $id=(int)($_POST['user_id']??0);role_portal_update_user($pdo,$id,(string)($_POST['full_name']??''),(string)($_POST['mobile']??''),(string)($_POST['role_code']??'customer'),!empty($_POST['is_active']));$success='Account #'.$id.' updated. Role changes revoke active sessions.';
        }elseif($action==='reset'){
            $id=(int)($_POST['user_id']??0);$p=(string)($_POST['temporary_password']??'');if(!hash_equals($p,(string)($_POST['confirm_password']??'')))throw new RuntimeException('Temporary password confirmation does not match.');security_step17_admin_reset_password($pdo,$id,$p);$success='Password reset for account #'.$id.'. Password change is required at next sign-in.';
        }
    }
    $users=security_step17_users($pdo,$orgId);$pendingRecovery=role_portal_pending_recovery_count($pdo,$orgId);
}catch(Throwable $e){$error=$e->getMessage();}
$labels=role_portal_roles();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Role Accounts - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"><link rel="stylesheet" href="assets/step10.css"><style>.role-cards{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:14px}.role-summary{padding:14px;border:1px solid #dfe8e3;border-radius:14px}.role-summary:nth-child(1){background:#eef9f3}.role-summary:nth-child(2){background:#eef5ff}.role-summary:nth-child(3){background:#f5f1ff}.role-summary h3{margin:0;font-size:.9rem}.role-summary p{margin:5px 0 0;color:#697a71;font-size:.7rem;line-height:1.5}@media(max-width:800px){.role-cards{grid-template-columns:1fr}}</style></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="security_center.php"><img src="../img/logo.png" alt="logo"><span><strong>Healthcare Wellness Club</strong><small>Advanced Login • Role Accounts</small></span></a><div class="os-top-actions"><a class="os-btn" href="account_security.php">Locks & Alerts</a><a class="os-btn" href="../account.php">My Account</a><a class="os-btn" href="password_recovery.php">Recovery <?=$pendingRecovery?'('.$pendingRecovery.')':''?></a><a class="os-btn" href="permission_matrix.php">Permissions</a><a class="os-btn primary" href="security_center.php">Security</a></div></div></header><div class="os-layout"><aside class="os-sidebar"><div class="os-nav-label">Role Login</div><nav class="os-nav"><a class="active" href="role_accounts.php"><i class="dot"></i>Role Accounts</a><a href="account_security.php"><i class="dot"></i>Locks & Security Alerts</a><a href="password_recovery.php"><i class="dot"></i>Password Recovery <?=$pendingRecovery?'('.$pendingRecovery.')':''?></a><a href="user_management.php"><i class="dot"></i>All Users</a><a href="security_sessions.php"><i class="dot"></i>Sessions</a><a href="security_audit.php"><i class="dot"></i>Audit</a><a href="../account.php"><i class="dot"></i>My Profile & Devices</a></nav><div class="os-sidebar-status"><b>Server-side role</b><span>The sign-in page never trusts a user-selected role. The database role determines the destination and permissions.</span></div></aside><main class="os-main"><section class="os-hero pp-hero"><div class="os-kicker">ADMIN • COACH • CUSTOMER</div><h1>Create one account, then let the server send each role to the correct workspace.</h1><p>Administrator has full Business OS control. Coach is restricted to customer/lead/product guidance. Customer stays outside the internal Business OS.</p><div class="role-cards"><div class="role-summary"><h3>Administrator</h3><p>Full security, finance, inventory, reports, backup and deployment controls.</p></div><div class="role-summary"><h3>Coach</h3><p>Customer CRM, leads, follow-ups, appointments and product view only by default.</p></div><div class="role-summary"><h3>Customer</h3><p>Private customer portal, storefront, cart and request history. No internal module permission.</p></div></div></section><?php if($error):?><div class="pp-alert bad"><strong>Role accounts:</strong> <?=security_step17_h($error)?></div><?php endif;?><?php if($success):?><div class="pp-alert good"><strong>Done:</strong> <?=security_step17_h($success)?></div><?php endif;?><?php if($pendingRecovery>0):?><div class="pp-alert" style="margin-top:14px"><strong><?=$pendingRecovery?> password recovery request(s) need review.</strong> <a href="password_recovery.php">Open Recovery Queue →</a></div><?php endif;?><section class="pp-grid"><article class="os-card pp-span-5"><h2>Create Login Account</h2><form method="post" class="pp-form" autocomplete="off"><input type="hidden" name="csrf" value="<?=security_step17_h($csrf)?>"><input type="hidden" name="action" value="create"><label>Full Name<input name="full_name" required maxlength="150"></label><label>Email / Login ID<input type="email" name="email" required maxlength="190"></label><label>Mobile<input name="mobile" maxlength="30"></label><label>Role<select name="role_code"><option value="customer">Customer</option><option value="coach">Coach</option><option value="admin">Administrator</option></select></label><label>Temporary Password<input type="password" name="temporary_password" required autocomplete="new-password"></label><label>Confirm Password<input type="password" name="confirm_password" required autocomplete="new-password"></label><div class="pp-alert"><strong>Policy:</strong> at least 12 characters with uppercase, lowercase, number and special character.</div><button>Create Secure Account</button></form></article><article class="os-card pp-span-7"><div class="os-title-row"><div><h2>Accounts</h2><p><?=count($users)?> account(s). Legacy internal roles are preserved for backward compatibility.</p></div><a class="os-btn" href="../login.php" target="_blank">Open Login →</a></div><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>User</th><th>Role</th><th>Status</th><th>Last Login</th><th>Sessions</th><th></th></tr></thead><tbody><?php foreach($users as $u):$role=(string)($u['role_code']??'viewer');?><tr><td><b><?=security_step17_h($u['full_name'])?></b><small><?=security_step17_h($u['email'])?><?=$u['mobile']?' • '.security_step17_h($u['mobile']):''?></small></td><td><span class="pp-badge"><?=security_step17_h(strtoupper($role))?></span></td><td><?=(int)$u['is_active']===1?'ACTIVE':'INACTIVE'?><?=(int)$u['must_change_password']===1?'<small>Password change required</small>':''?></td><td><?=security_step17_h($u['last_login_at']?:'Never')?></td><td><?=(int)$u['active_sessions']?></td><td><details><summary>Manage</summary><form method="post" class="pp-form" style="min-width:270px"><input type="hidden" name="csrf" value="<?=security_step17_h($csrf)?>"><input type="hidden" name="action" value="update"><input type="hidden" name="user_id" value="<?=(int)$u['id']?>"><label>Name<input name="full_name" value="<?=security_step17_h($u['full_name'])?>" required></label><label>Mobile<input name="mobile" value="<?=security_step17_h($u['mobile']??'')?>"></label><label>Role<select name="role_code"><?php foreach($labels as $k=>$v):?><option value="<?=security_step17_h($k)?>" <?=$role===$k?'selected':''?>><?=security_step17_h($v)?></option><?php endforeach;?></select></label><label class="pp-check"><input type="checkbox" name="is_active" value="1" <?=(int)$u['is_active']===1?'checked':''?>> Active account</label><button>Save Access</button></form><hr><form method="post" class="pp-form" autocomplete="off"><input type="hidden" name="csrf" value="<?=security_step17_h($csrf)?>"><input type="hidden" name="action" value="reset"><input type="hidden" name="user_id" value="<?=(int)$u['id']?>"><label>New Temporary Password<input type="password" name="temporary_password" required autocomplete="new-password"></label><label>Confirm<input type="password" name="confirm_password" required autocomplete="new-password"></label><button>Reset Password & Revoke Sessions</button></form></details></td></tr><?php endforeach;?></tbody></table></div></article></section><div class="os-footer-note"><strong>Important:</strong> Customer is intentionally not granted Business OS permissions. Coach defaults are limited and can be expanded later only through Administrator-controlled policy.</div></main></div><script src="assets/business-collapsible.js?v=20260820-1" defer></script></body></html>
